    "question": "(Soal HOTS Komposisi Seni) Seorang pelukis ingin menciptakan kesan ruang dan kedalaman (tiga dimensi) pada permukaan kanvas datar dua dimensi. Teknik seni rupa yang paling tepat digunakan adalah...",
